export const BASE_URL =
  process.env.REACT_APP_API_BASE_URL || "https://cardscan.up.railway.app";

export const TENANT_UPLOAD_URLS = {
  demoapp: "https://demoapp.sandlus.in/upload-image.php",
  futuretechsys: "https://futuretechsys.sandlus.in/upload-image.php",
  message: "https://message.sandlus.in/upload-image.php",
  desipos: "https://cardscan.desithread.co.in/upload-image.php"
};


export const getTenantSlugFromPath = () => {
  const parts = window.location.pathname.split("/").filter(Boolean);

  if (parts.length >= 2 && parts[0] === "client") {
    return parts[1].toLowerCase();
  }

  return "demoapp";
};

export const getTenantHeaders = (extraHeaders = {}) => {
  const tenantSlug = getTenantSlugFromPath();

  return {
  "X-Tenant-Slug": tenantSlug,
  ...extraHeaders,
};
};

export const getTenantUploadUrl = (tenantSlug) => {
  return TENANT_UPLOAD_URLS[(tenantSlug || "").toLowerCase()] || "";
};