function CountryDropdown({ name, value, onChange }) {
  const [open, setOpen] = useState(false);
  const dropdownRef = useRef(null);

  const selectedCountry =
    COUNTRY_OPTIONS.find((country) => country.value === value) ||
    COUNTRY_OPTIONS[0];

  useEffect(() => {
    const handleOutsideClick = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setOpen(false);
      }
    };

    document.addEventListener("mousedown", handleOutsideClick);
    return () => document.removeEventListener("mousedown", handleOutsideClick);
  }, []);

  const handleSelect = (country) => {
    onChange({
      target: {
        name,
        value: country.value,
      },
    });
    setOpen(false);
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        type="button"
        onClick={() => setOpen((prev) => !prev)}
        className="flex h-full min-w-[105px] items-center gap-2 rounded-l-xl border-r border-gray-300 bg-slate-50 px-3 py-2 text-sm text-gray-900"
      >
        <ReactCountryFlag
          countryCode={selectedCountry.value}
          svg
          style={{ width: "1.25em", height: "1.25em" }}
          title={selectedCountry.label}
        />
        <span>{selectedCountry.code}</span>
        <ChevronDown size={15} className="ml-auto text-gray-500" />
      </button>

      {open && (
        <div className="absolute left-0 top-full z-30 mt-2 max-h-64 w-60 overflow-auto rounded-xl border border-gray-200 bg-white shadow-lg">
          {COUNTRY_OPTIONS.map((country) => (
            <button
              key={country.value}
              type="button"
              onClick={() => handleSelect(country)}
              className="flex w-full items-center gap-3 px-3 py-2 text-left text-sm hover:bg-gray-50"
            >
              <ReactCountryFlag
                countryCode={country.value}
                svg
                style={{ width: "1.25em", height: "1.25em" }}
                title={country.label}
              />
              <span>{country.label}</span>
              <span className="ml-auto text-gray-500">{country.code}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

