import React from "react";
import { X } from "lucide-react";

const FIELD_LABELS = {
  level: "Level",
  customerCompany: "Customer Company",
  personName: "Person Name",
  designation: "Designation",
  mobile: "Mobile",
  email: "Email",
  address: "Address",
  notes: "Notes",
};

function QrFieldPicker({
  open,
  onClose,
  qrSelections = [],
  targetField,
  onSelectValue,
}) {
  if (!open) return null;

  const label = FIELD_LABELS[targetField] || "Selected Field";

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-center justify-center p-4">
      <div className="w-full max-w-lg rounded-2xl bg-white border border-slate-200 shadow-2xl overflow-hidden">
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-200 bg-slate-50">
          <div>
            <h2 className="text-lg font-bold text-slate-800">QR Data</h2>
            <p className="text-sm text-slate-500">
              Select data for: <span className="font-semibold">{label}</span>
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="h-10 w-10 rounded-full hover:bg-slate-200 flex items-center justify-center"
          >
            <X size={18} />
          </button>
        </div>

        <div className="p-5 max-h-[70vh] overflow-y-auto">
          {qrSelections.length ? (
            <div className="space-y-3">
              {qrSelections.map((item, index) => (
                <button
                  key={`${item.value}-${index}`}
                  type="button"
                  onClick={() => {
                    onSelectValue(targetField, item.value);
                    onClose();
                  }}
                  className="w-full text-left rounded-xl border border-slate-200 bg-slate-50 hover:bg-indigo-50 hover:border-indigo-300 p-4 transition"
                >
                  <p className="text-xs font-semibold uppercase tracking-wide text-indigo-600 mb-1">
                    {item.label}
                  </p>
                  <p className="text-sm text-slate-800 break-words">
                    {item.value}
                  </p>
                </button>
              ))}
            </div>
          ) : (
            <div className="rounded-xl border border-slate-200 bg-slate-50 p-4">
              <p className="text-slate-500">No QR data found.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default QrFieldPicker; 
