import React from "react";
import { X } from "lucide-react";

const FIELD_LABELS = {
  customerCompany: "Customer Company",
  personName: "Person Name",
  designation: "Designation",
  mobile: "Mobile",
  mobile2: "Mobile 2",
  email: "Email",
  email2: "Email 2",
  address: "Address",
  notes: "Notes",
  gstin: "GSTIN",
  website: "Website",
};

export default function BusinessFieldPicker({
  open,
  onClose,
  selections = [],
  targetField,
  onSelectValue,
}) {
  if (!open) return null;

  const label = FIELD_LABELS[targetField] || "Selected Field";

  return (
    <div className="fixed inset-0 z-[999] flex items-center justify-center bg-black/40 px-4">
      <div className="w-full max-w-lg overflow-hidden rounded-3xl bg-white shadow-2xl">
        <div className="flex items-start justify-between border-b border-gray-100 px-5 py-4">
          <div>
            <h3 className="text-lg font-bold text-gray-900">
              Select data for: {label}
            </h3>
            <p className="mt-1 text-sm text-gray-500">
              Choose detected text and fill the field instantly.
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-full p-2 text-gray-400 transition hover:bg-gray-100 hover:text-gray-700"
          >
            <X size={18} />
          </button>
        </div>

        <div className="max-h-[420px] overflow-y-auto px-4 py-4">
          {!selections.length ? (
            <div className="rounded-2xl border border-dashed border-gray-200 bg-gray-50 px-4 py-8 text-center text-sm text-gray-500">
              No business card data found.
            </div>
          ) : (
            <div className="space-y-3">
              {selections.map((item, index) => (
                <button
                  key={`${item.label}-${item.value}-${index}`}
                  type="button"
                  onClick={() => onSelectValue(targetField, item.value)}
                  className="w-full rounded-2xl border border-gray-200 bg-white px-4 py-2 text-left transition hover:border-blue-300 hover:bg-blue-50"
                >
                  <div className="text-xs font-semibold uppercase tracking-wide text-blue-600">
                    {item.label}
                  </div>
                  <div className="mt-1 break-words text-sm font-medium text-gray-800">
                    {item.value}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="border-t border-gray-100 px-5 py-4">
          <button
            type="button"
            onClick={onClose}
            className="h-11 w-full rounded-xl border border-gray-200 bg-white text-sm font-semibold text-gray-700 transition hover:bg-gray-50"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}