import { useState } from "react";
import { getTenantSlugFromPath } from "../config";

const TENANT_API_URLS = {
  demoapp: "https://demoapp.sandlus.in/api/sendMsg",
  message: "https://message.sandlus.in/api/sendMsg",
  futuretechsys: "https://futuretechsys.sandlus.in/api/sendMsg",
};

function SendMessage({ imageName = "" }) {
  const tenantSlug = (getTenantSlugFromPath() || "demoapp").toLowerCase();

  const SEND_MSG_API =
    TENANT_API_URLS[tenantSlug] || "https://demoapp.sandlus.in/api/sendMsg";

  const emptyForm = {
    type: "",
    level: "",
    category: "",
    product: "",
    item_data: [],
    customerCompany: "",
    personName: "",
    designation: "",
    mobile: "",
    mobile2: "",
    email: "",
    email2: "",
    address: "",
    notes: "",
    qtyScope: "",
    image_name: imageName,
  };

  const [formData, setFormData] = useState(emptyForm);
  const [loading, setLoading] = useState(false);

  const formatIndianMobile = (number) => {
  const digits = String(number || "").replace(/\D/g, "");

  if (!digits) return "";

  // already has 91
  if (digits.startsWith("91") && digits.length === 12) {
    return digits;
  }

  // take last 10 digits and add 91
  if (digits.length >= 10) {
    return `91${digits.slice(-10)}`;
  }

  return digits;
};

  const handleChange = (e) => {
    const { name, value } = e.target;

    if (name === "mobile" || name === "mobile2") {
      setFormData((prev) => ({
        ...prev,
        [name]: value.replace(/\D/g, "").slice(-10),
      }));
      return;
    }

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const payload = {
      tenant: tenantSlug,

      type: formData.type,
      level: formData.level,
      category: formData.category,
      product: formData.product,
      item_data: formData.item_data,

      customerCompany: formData.customerCompany,
      personName: formData.personName,
      designation: formData.designation,

      mobile: formatIndianMobile(formData.mobile),
      mobile2: formatIndianMobile(formData.mobile2),
      email: formData.email,
      email2: formData.email2,

      address: formData.address,
      notes: formData.notes,
      qtyScope: formData.qtyScope,

      image_name: formData.image_name || imageName,
    };

    try {
      const response = await fetch(SEND_MSG_API, {
        method: "POST",
        headers: {
          "Content-Type": "text/plain;charset=UTF-8",
        },
        body: JSON.stringify(payload),
      });

      const text = await response.text();

      console.log("📨 PHP Response:", text);

      if (response.ok) {
        alert("✅ Message sent successfully");
        setFormData(emptyForm);
      } else {
        alert("❌ Error: " + text);
      }
    } catch (error) {
      console.error(error);
      alert("❌ Server error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 max-w-md mx-auto bg-white rounded-xl shadow">
      <h2 className="text-xl font-bold mb-4">Send Message</h2>

      <form onSubmit={handleSubmit} className="space-y-3">
        <input
          name="customerCompany"
          value={formData.customerCompany}
          onChange={handleChange}
          placeholder="Company"
          className="w-full border p-2 rounded"
        />

        <input
          name="personName"
          value={formData.personName}
          onChange={handleChange}
          placeholder="Name"
          className="w-full border p-2 rounded"
        />

        <input
          name="mobile"
          value={formData.mobile}
          onChange={handleChange}
          placeholder="Mobile"
          className="w-full border p-2 rounded"
        />

        <input
          name="email"
          value={formData.email}
          onChange={handleChange}
          placeholder="Email"
          className="w-full border p-2 rounded"
        />

        <textarea
          name="notes"
          value={formData.notes}
          onChange={handleChange}
          placeholder="Message"
          className="w-full border p-2 rounded"
        />

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-indigo-600 text-white p-2 rounded"
        >
          {loading ? "Sending..." : "Send Message"}
        </button>
      </form>
    </div>
  );
}

export default SendMessage;