
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import ScanAndFill from './components/ScanAndFill';
import BusinessCardScan from './components/BusinessCardScan';
import SendMessage from './components/SendMessage';
import BarcodeScan from './components/BarcodeScan';
import TenantLogin from "./components/TenantLogin";
import ProtectedRoute from "./components/ProtectedRoute";
import './index.css';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Navigate to="/client/demoapp" replace />} />
        <Route
  path="/client/:tenantSlug/login"
  element={<TenantLogin />}
/>
        <Route
  path="/client/:tenantSlug"
  element={
    <ProtectedRoute>
      <ScanAndFill />
    </ProtectedRoute>
  }
/>

<Route
  path="/client/:tenantSlug/business-card"
  element={
    <ProtectedRoute>
      <BusinessCardScan />
    </ProtectedRoute>
  }
/>

<Route
  path="/client/:tenantSlug/qrscan"
  element={
    <ProtectedRoute>
      <ScanAndFill />
    </ProtectedRoute>
  }
/>
        <Route path="/send-message" element={<SendMessage />} />
        <Route
  path="/client/:tenantSlug/fastbill"
  element={
    <ProtectedRoute>
      <BarcodeScan />
    </ProtectedRoute>
  }
/>
      </Routes>
    </BrowserRouter>
  );
}

export default App;



